 g.strokeStyle='#cdbb8a';g.lineWidth=3*ratio;for(const br of DATA.river.bridges){g.beginPath();g.moveTo(...xy(DATA.river.west-5,br.z));g.lineTo(...xy(DATA.river.east+5,br.z));g.stroke();}
