function marketInfo(){const k=['tuna','battery','wire','med'][Math.floor(state.clock/1440)%4];return{kind:k,text:`Wanted today: ${CAT[k].name}. Paying 2.5× the usual price.`,price:kind=>Math.ceil(CAT[kind].value*(kind===k?2.5:1))}}
let gossipIndex=0;
function gossipText(){const texts=['The west ridge lodge has an upstairs equipment chest. Take the stairs on the right. Someone left a patrol carbine there.','A tiny substation hides a large storage shelter. The stairs go down. Listen before you reach the last step.','The low clicking is a skitter. When it crouches to leap, step sideways. It commits to the place you were standing.','The red areas on your map are anomaly fields. A detector reveals what is hidden; probes reveal a temporary eastern route.','The quartermaster is paying extra for '+CAT[marketInfo().kind].name.toLowerCase()+' today.','Hollowstone cave has survey film in a supply chest. The map changes when you enter. Bring a torch and spare batteries.'];return texts[(gossipIndex++)%texts.length]}
